insert into assessment_sections (id, assessment_id, ord, title, pdf_title, pdf_page, teacher_note) values ('rsm-4-7-diagnostic-2026-08:s05', 'rsm-4-7-diagnostic-2026-08', 5, '공배수, 공약수, 분수', null, 6, '본 테스트 과정에는 없는 내용으로 중1 과정에서 학습하는 거듭제곱을 “읽고 말하는 수학” 에서는 2권에서 학습합니다. 자연수의 짝수와 배수, 소수와 합성수, 약수와 인수 등 개념을 정확하게 학습하게 되면 수학이라는 학문의 부분과 전체를 이해하는 데 도움이 됩니다.');
