insert into assessment_items (id, part_id, ord, label, type, grading, stem, blanks, choices, model_answer, figure, review_note, tags) values ('rsm-4-7-diagnostic-2026-08:s05-p2-06', 'rsm-4-7-diagnostic-2026-08:s05:p2', 6, '⑥', 'fill', 'auto', '[{"t": "rich", "v": "피자 한 판의 $\\dfrac{2}{5}$만큼 먹었다. 먹고 남은 피자는 얼마인가?"}, {"t": "blank", "id": "b1"}, {"t": "rich", "v": "판,"}, {"t": "blank", "id": "b2"}, {"t": "rich", "v": "조각"}]'::jsonb, '[{"id": "b1", "kind": "rational", "answer": "3/5"}, {"id": "b2", "kind": "int", "answer": "3"}]'::jsonb, null, null, null, '''조각'' 답(3)은 피자를 5조각으로 나눴다고 가정한 값입니다. PDF에 조각 수 조건이 없어 확인이 필요합니다.', array['frac_word']::text[]);
