insert into assessment_sections (id, assessment_id, ord, title, pdf_title, pdf_page, teacher_note) values ('rsm-4-7-diagnostic-2026-08:s06', 'rsm-4-7-diagnostic-2026-08', 6, '연산 법칙과 응용문제', null, 7, '법칙적 연산을 인지 여부를 확인하는 테스트 페이지입니다. 곱셈과 나눗셈을 기계적인 연산이 아닌 234×5는 234가 다섯이라는 개념의 인지 여부를 확인합니다. 분수의 곱셈은 왜 “분자끼리 곱하고 분모끼리 곱하는” 원리의 이해 여부를 확인하는 페이지입니다. 분수의 나눗셈은 왜 역수로 곱하는지 등을 테스트합니다. 분수 나머지 비율의 이해. 사과를 2/5의 나머지를 구체적인 것과 형식적인 내용을 모두 인지하는지를 확인합니다.');
