insert into assessment_items (id, part_id, ord, label, type, grading, stem, blanks, choices, model_answer, figure, review_note, tags) values ('rsm-4-7-diagnostic-2026-08:s06-p2-01', 'rsm-4-7-diagnostic-2026-08:s06:p2', 1, '①', 'fill', 'mixed', '[{"t": "rich", "v": "다음을 계산하고 구하는 방법을 설명하시오. $\\dfrac{1}{4}\\times\\dfrac{1}{3}=$"}, {"t": "blank", "id": "b1"}, {"t": "rich", "v": "/ 설명:"}, {"t": "blank", "id": "ex"}]'::jsonb, '[{"id": "b1", "kind": "rational", "answer": "1/12"}, {"id": "ex", "kind": "text", "answer": ""}]'::jsonb, null, '분자끼리, 분모끼리 곱합니다. 1/4의 1/3은 한 칸을 다시 3등분한 것이라 전체의 1/12입니다.', null, null, array['frac_mul']::text[]);
