insert into assessment_parts (id, section_id, ord, title, timed) values ('rsm-4-7-diagnostic-2026-08:s11:p1', 'rsm-4-7-diagnostic-2026-08:s11', 1, '도형과 비', false);
insert into assessment_items (id, part_id, ord, label, type, grading, stem, blanks, choices, model_answer, figure, review_note, tags) values ('rsm-4-7-diagnostic-2026-08:s11-p1-01', 'rsm-4-7-diagnostic-2026-08:s11:p1', 1, '1.', 'fill', 'auto', '[{"t": "rich", "v": "세 변의 길이의 비가 5:4:3인 직각삼각형의 둘레가 36㎝일 때, 이 삼각형의 넓이를 구하시오."}, {"t": "blank", "id": "b1"}, {"t": "rich", "v": "㎠"}]'::jsonb, '[{"id": "b1", "kind": "int", "answer": "54"}]'::jsonb, null, null, 'figures/s11-q1-triangle.svg', null, array['ratio_geometry']::text[]);
insert into assessment_items (id, part_id, ord, label, type, grading, stem, blanks, choices, model_answer, figure, review_note, tags) values ('rsm-4-7-diagnostic-2026-08:s11-p1-02', 'rsm-4-7-diagnostic-2026-08:s11:p1', 2, '2.', 'fill', 'auto', '[{"t": "rich", "v": "$\\dfrac{1}{4}a = \\dfrac{3}{14}b$일 때 $a$와 $b$를 가장 작은 자연수의 비를 구하시오. $a : b =$"}, {"t": "blank", "id": "b1"}, {"t": "rich", "v": "$:$"}, {"t": "blank", "id": "b2"}]'::jsonb, '[{"id": "b1", "kind": "int", "answer": "6"}, {"id": "b2", "kind": "int", "answer": "7"}]'::jsonb, null, null, null, null, array['ratio_simplest']::text[]);
insert into assessment_items (id, part_id, ord, label, type, grading, stem, blanks, choices, model_answer, figure, review_note, tags) values ('rsm-4-7-diagnostic-2026-08:s11-p1-03', 'rsm-4-7-diagnostic-2026-08:s11:p1', 3, '3.', 'fill', 'mixed', '[{"t": "rich", "v": "다음 색칠한 부분의 둘레와 넓이를 구하는 식을 쓰시오. 둘레:"}, {"t": "blank", "id": "b1"}, {"t": "rich", "v": "㎝ / 넓이:"}, {"t": "blank", "id": "b2"}, {"t": "rich", "v": "㎠"}]'::jsonb, '[{"id": "b1", "kind": "expr", "answer": "10π", "accept": ["10*π", "10pi", "31.4"]}, {"id": "b2", "kind": "expr", "answer": "8π", "accept": ["25.12", "8*π", "8pi"]}]'::jsonb, null, '둘레 = (10×π÷2) + (4×π÷2) + (2×π÷2) + (4×π÷2) = 10π (π=3.14이면 31.4㎝). 넓이 = (5×5×π÷2) − (2×2×π÷2 + 1×1×π÷2 + 2×2×π÷2) = 8π (π=3.14이면 25.12㎠).', 'figures/s11-q3-semicircles.svg', '''식을 쓰시오''라 채점은 식 확인(수동)을 권장합니다. 숫자 답은 참고용입니다.', array['circle_area_perimeter']::text[]);
insert into assessment_items (id, part_id, ord, label, type, grading, stem, blanks, choices, model_answer, figure, review_note, tags) values ('rsm-4-7-diagnostic-2026-08:s11-p1-04', 'rsm-4-7-diagnostic-2026-08:s11:p1', 4, '4.', 'fill', 'auto', '[{"t": "rich", "v": "다음 도형에서 $\\angle x$의 값을 구하시오."}, {"t": "blank", "id": "b1"}, {"t": "rich", "v": "°"}]'::jsonb, '[{"id": "b1", "kind": "int", "answer": "24"}]'::jsonb, null, null, 'figures/s11-q4-angle.svg', '그림의 같은 길이 표시가 BD=BC=CD(정삼각형)라서 ∠BCD=60°, ∠ACB=180−84−60=36°, ∠ABC=120°, x=24°입니다. 교과서의 흔한 유형(AB=BC=CD, 외각 84°)이라면 x=28°이므로 그림 의도를 확인해 주세요.', array['angle_isosceles']::text[]);
