insert into assessment_items (id, part_id, ord, label, type, grading, stem, blanks, choices, model_answer, figure, review_note, tags) values ('rsm-4-7-diagnostic-2026-08:s12-p2-01', 'rsm-4-7-diagnostic-2026-08:s12:p2', 1, '①', 'fill', 'auto', '[{"t": "rich", "v": "$(a+b)^{2}=$"}, {"t": "blank", "id": "b1"}]'::jsonb, '[{"id": "b1", "kind": "expr", "answer": "a^2+2ab+b^2", "accept": ["a²+2ab+b²"]}]'::jsonb, null, null, null, null, array['expansion']::text[]);
insert into assessment_items (id, part_id, ord, label, type, grading, stem, blanks, choices, model_answer, figure, review_note, tags) values ('rsm-4-7-diagnostic-2026-08:s12-p2-02', 'rsm-4-7-diagnostic-2026-08:s12:p2', 2, '②', 'fill', 'auto', '[{"t": "rich", "v": "$\\dfrac{1}{(a+b)}+\\dfrac{1}{(a-b)}=$"}, {"t": "blank", "id": "b1"}]'::jsonb, '[{"id": "b1", "kind": "expr", "answer": "2a/(a^2-b^2)", "accept": ["2a/((a+b)(a-b))", "2a/(a²-b²)"]}]'::jsonb, null, null, null, null, array['rational_expression']::text[]);
insert into assessment_parts (id, section_id, ord, title, timed) values ('rsm-4-7-diagnostic-2026-08:s12:p3', 'rsm-4-7-diagnostic-2026-08:s12', 3, '3. 다음 해를 구하는 식을 쓰시오.', false);
insert into assessment_items (id, part_id, ord, label, type, grading, stem, blanks, choices, model_answer, figure, review_note, tags) values ('rsm-4-7-diagnostic-2026-08:s12-p3-01', 'rsm-4-7-diagnostic-2026-08:s12:p3', 1, '1)', 'fill', 'mixed', '[{"t": "rich", "v": "연속하는 세 짝수의 합이 42일 때, 이 세 짝수를 구하는 식을 쓰시오. 식:"}, {"t": "blank", "id": "expr"}, {"t": "rich", "v": "세 짝수:"}, {"t": "blank", "id": "b1"}, {"t": "rich", "v": ","}, {"t": "blank", "id": "b2"}, {"t": "rich", "v": ","}, {"t": "blank", "id": "b3"}]'::jsonb, '[{"id": "expr", "kind": "text", "answer": ""}, {"id": "b1", "kind": "int", "answer": "12"}, {"id": "b2", "kind": "int", "answer": "14"}, {"id": "b3", "kind": "int", "answer": "16"}]'::jsonb, null, '연속하는 세 짝수의 합은 x−2, x, x+2, 연속하는 세 짝수를 구하는 식은 x−2+x+x+2=42 ⇒ 3x=42 ⇒ x=14', null, 'PDF에 파란 글씨로 예시 답이 적혀 있습니다(교사용 예시). 학생 화면에는 숨기고 해설로 쓰는 것을 권장합니다.', array['linear_word']::text[]);
insert into assessment_items (id, part_id, ord, label, type, grading, stem, blanks, choices, model_answer, figure, review_note, tags) values ('rsm-4-7-diagnostic-2026-08:s12-p3-02', 'rsm-4-7-diagnostic-2026-08:s12:p3', 2, '2)', 'fill', 'mixed', '[{"t": "rich", "v": "어느 농장에서 오리와 염소를 합해 20마리를 기르는데 다리를 세어보니 다리의 합이 54개이다. 이 농장에서 기르는 염소와 오리는 각각 몇 마리인가? 식:"}, {"t": "blank", "id": "expr"}, {"t": "rich", "v": "염소:"}, {"t": "blank", "id": "b1"}, {"t": "rich", "v": "마리, 오리:"}, {"t": "blank", "id": "b2"}, {"t": "rich", "v": "마리"}]'::jsonb, '[{"id": "expr", "kind": "text", "answer": ""}, {"id": "b1", "kind": "int", "answer": "7"}, {"id": "b2", "kind": "int", "answer": "13"}]'::jsonb, null, '오리를 x마리라 하면 2x + 4(20−x) = 54 ⇒ x = 13. 오리 13마리, 염소 7마리', null, null, array['linear_word']::text[]);
